#include <time.h>
static double now(void){struct timespec t;timespec_get(&t,TIME_UTC);return t.tv_sec+t.tv_nsec*1e-9;}
static bounce_triangle attrs[2048];
static bounce_vertex unique[6144];
static unsigned used;
static void add(bounce_vertex x){for(unsigned i=0;i<used;i++)if(!memcmp(unique+i,&x,sizeof x))return;unique[used++]=x;}
int main(int argc,char **argv){printf("header=%zu attr_offset=%zu vertex=%zu triangle=%zu lights=%zu ground=%zu\n",sizeof(bounce_scene),offsetof(bounce_scene,attrs),sizeof(bounce_vertex),sizeof(bounce_triangle),sizeof(FoxDiskScene),sizeof(bounce_ground));for(int a=1;a<argc;a++){FILE*f=fopen(argv[a],"rb");assert(f);fseek(f,0,SEEK_END);long size=ftell(f);rewind(f);unsigned char*b=malloc(size);assert(b&&fread(b,1,size,f)==(size_t)size);fclose(f);used=0;unsigned tris=0;size_t at=416;while(at<(size_t)size){co_view v;assert(co_read(b+at,size-at,&v));for(unsigned t=0;t<v.triangle_count;t++){uint8_t ix[3];assert(co_triangle_at(&v,t,ix));for(unsigned j=0;j<3;j++){co_pixel_vertex p;assert(co_pixel_vertex_at(&v,ix[j],&p));bounce_vertex x={0};x.front[0]=p.normal_front[0];x.front[1]=-p.normal_front[2];x.front[2]=-p.normal_front[1];x.back[0]=p.normal_back[0];x.back[1]=-p.normal_back[2];x.back[2]=-p.normal_back[1];memcpy(&x.mask,&p.front.mask,4);x.a565=p.front.color_a;x.b565=p.front.color_b;add(x);attrs[tris+t].v[j]=x;attrs[tris+t].double_sided=1 /* Synthetic sidedness; snapshot count proof concerns complete vertex bytes only. */;}}tris+=v.triangle_count;at+=v.size;}assert(at==(size_t)size);unsigned character=used;bounce_vertex floor={.front={0,0,32767},.back={0,0,-32767}};add(floor);for(unsigned t=tris;t<tris+2;t++){attrs[t].double_sided=1;for(unsigned j=0;j<3;j++)attrs[t].v[j]=floor;} unsigned nt=tris+2;
 double xyz[]={0,0,0,1,0,0,0,1,0};uint32_t *indices=calloc(nt*3,sizeof(*indices));for(unsigned t=0;t<nt;t++){indices[3*t+1]=1;indices[3*t+2]=2;}vis_scene *geometry=NULL;vis_generation vg={1,1,1};assert(vis_scene_build(&geometry,xyz,3,indices,nt,vg,(vis_limits){2048,4095,524288})==VIS_OK);free(indices);
 FoxDiskScene lights;FoxDiskLightInput li[3]={0};for(int k=0;k<3;k++){li[k].shape=FOX_DISK_SHAPE_DISK;li[k].diameter=.2;li[k].power=1;li[k].center[2]=5;}double world[]={.25,.5,1};assert(fox_disk_scene_init(&lights,li,world,1)==FOX_DISK_OK);
 double start=now();size_t bytes=bounce_scene_compact_required_bytes(attrs,nt);double query=now()-start;bounce_scene *scene=NULL;bounce_generation bg={vg,1,0};start=now();assert(bounce_scene_build_ground_compact(&scene,geometry,attrs,nt,&lights,-1,bg,262144,NULL)==BOUNCE_OK);double build=now()-start;assert(bytes==28592&&scene->bytes==bytes);for(unsigned t=0;t<nt;t++)for(unsigned j=0;j<3;j++)assert(!memcmp(&attrs[t].v[j],material_vertex(scene,t,j),20));printf("built_bytes=%zu unique=%zu query_ms=%.3f build_ms=%.3f ",bytes,(bytes-584-8*nt)/20,query*1000,build*1000);bounce_scene_release(scene);vis_scene_release(geometry);
 printf("%s triangles=%u character_unique=%u with_ground=%u\n",argv[a],tris,character,used);assert(tris==1564&&character==773&&used==774);free(b);}return 0;}
